impl crate::qualification::TortTemplate {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::qualification::TortTemplateWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"tort_type\", \"firm_id\", \"version\", \"display_name\", \"schema_version\", \"s3_bucket\", \"s3_key\", \"content_hash\", \"status\", \"published_at\", \"published_by\", \"created_at\", \"updated_at\"";
        let mut qb =
            sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "tort_templates" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

impl crate::qualification::TortTemplate {
    pub async fn find_first<'e, E>(
        executor: E,
        w: &crate::qualification::TortTemplateWhereInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let mut qb = sqlx::QueryBuilder::new(
            r#"SELECT "id", "tort_type", "firm_id", "version", "display_name", "schema_version", "s3_bucket", "s3_key", "content_hash", "status", "published_at", "published_by", "created_at", "updated_at" FROM "tort_templates" WHERE "#,
        );
        if !crate::engine::sqlx_postgres::qualification::push_tort_template_where(&mut qb, w) {
            qb.push("TRUE");
        }
        qb.push(" LIMIT 1");
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

